{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "In rats, a closely related 1,3,5-triazine with an amino and N-methylpiperazine substituent crossed the blood-brain barrier well (Kp=2.03), directly supporting meaningful CNS access for the query's triazine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A morpholine-containing heteroaromatic amide achieved Kp=11.4 in mice with negligible P-gp efflux, showing that polar morpholine-substituted chemotypes can be excellent CNS penetrants.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A morpholine-aniline pyrimidine amide reached 100% brain/plasma ratio, supporting CNS access for morpholine-substituted heteroaromatic anilines similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A morpholine-substituted fused heteroaromatic showed favorable brain uptake in rodent autoradiography/PET, reinforcing that morpholine heteroaromatics can penetrate the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A CF3-aryl heteroaromatic brain-penetrant inhibitor had CSF/Cbu=0.87 in rats, showing the trifluoromethyl aryl motif is compatible with good CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Multiple high-transfer in vivo CNS-penetration measurements in closely related triazine/morpholine/CF3-aryl chemotypes (Kp 2.03-11.4, 100% brain/plasma, CSF/Cbu 0.87, PET uptake) outweigh the physicochemical prior of low passive permeability. The single poor-penetration record has low transferability and does not overturn the consistent positive evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule; prediction is based on transferable analogues.",
    "The low-transfer poor-penetration record C01 was considered but not weighted heavily because its assay context is not transferable to the query.",
    "Efflux-transporter status of the query is not directly measured, but high-transfer analogues with similar morpholine/triazine features showed good CNS exposure and, in one case, negligible P-gp efflux."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

